import { formatUnits } from 'viem'
import { robinhoodChain } from './robinhoodChain.js'

export const CHAIN_CONFIG = {
  [robinhoodChain.id]: { name: 'Robinhood Chain', currency: 'ETH', explorer: 'https://rh-scan.com' },
}

export function getChainInfo(chainId) {
  return CHAIN_CONFIG[chainId] || { name: 'Unknown', currency: 'ETH', explorer: '' }
}

export function getTxUrl(chainId, hash) {
  const info = getChainInfo(chainId)
  return info.explorer ? `${info.explorer}/tx/${hash}` : null
}

export function getAddressUrl(chainId, address) {
  const info = getChainInfo(chainId)
  return info.explorer ? `${info.explorer}/address/${address}` : null
}

export function fmtErr(e) {
  const msg = e?.shortMessage || e?.message || ''
  if (msg.includes('reverted') || msg.includes('revert')) return 'Transaction failed — please try again'
  if (msg.includes('rejected') || msg.includes('denied') || msg.includes('cancelled')) return 'Transaction rejected'
  if (msg.includes('insufficient funds')) return 'Insufficient funds for gas'
  return msg || 'Unknown error'
}

// Display-only truncation (no rounding). Input fields use full formatUnits string.
export function fmtDisplay(raw, decimals, maxDec = 6) {
  const s = formatUnits(raw, decimals)
  const dot = s.indexOf('.')
  if (dot === -1) return s
  return s.slice(0, dot + 1 + maxDec).replace(/\.?0+$/, '') || '0'
}
