import { useChainId, useAccount, useSwitchChain } from 'wagmi'
import { useState, useEffect } from 'react'
import { SUPPORTED_CHAIN_IDS } from './config.js'
import { robinhoodChain } from './robinhoodChain.js'

const KEY = 'uc_guest_chain'
const DEFAULT = robinhoodChain.id

function getStored() {
  const v = parseInt(localStorage.getItem(KEY))
  return SUPPORTED_CHAIN_IDS.includes(v) ? v : DEFAULT
}

// Global state so all consumers stay in sync
let _listeners = []
let _guestChainId = getStored()

function setGuestChainId(id) {
  _guestChainId = id
  localStorage.setItem(KEY, id)
  _listeners.forEach(fn => fn(id))
}

export function useGuestChain() {
  const { isConnected } = useAccount()
  const walletChainId = useChainId()
  const { switchChain } = useSwitchChain()
  const [guestId, setGuestId] = useState(_guestChainId)

  useEffect(() => {
    _listeners.push(setGuestId)
    return () => { _listeners = _listeners.filter(f => f !== setGuestId) }
  }, [])

  const activeChainId = isConnected ? walletChainId : guestId

  function selectChain(chainId) {
    if (isConnected) switchChain({ chainId })
    else setGuestChainId(chainId)
  }

  return { activeChainId, selectChain, isConnected }
}
